# Generated by build.py from recipe.yml for recipe sftp-upload-and-rename. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'other' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'notes.txt'), "uploaded by curl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'other/readme.txt'), "read me`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--throwaway-hostkey', '--user', 'alice:s3cret', '--allow-uploads', '--list-directories', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -k -u alice:s3cret -T notes.txt -Q "-rename /notes.part /notes.txt" sftp://127.0.0.1:8080/notes.part } finally { Stop-Process $server0 }
